import { handleTelegramRequest, isUserBlocked, readAdminSetting } from './admin.js';
const EMBEDDED_APP_JS = "const API_BASE = '';\nconst NEWS_URL = '';\nconst CHAT_URL = '';\nconst tg = window.Telegram?.WebApp;\nfunction syncTelegramViewport(){\n  if(!tg) return;\n  try { tg.expand(); tg.setHeaderColor?.('#06101d'); tg.setBackgroundColor?.('#06101d'); } catch(e) {}\n  document.documentElement.style.setProperty('--tg-viewport-height', ((tg.viewportHeight || window.innerHeight) + 'px'));\n  document.documentElement.style.setProperty('--tg-stable-viewport-height', ((tg.viewportStableHeight || tg.viewportHeight || window.innerHeight) + 'px'));\n}\nconst state = { user:null, config:null, ready:false, busy:false, activePage:'mine', adController:null, demo:false }; let regenTimer=null;\nconst $ = id => document.getElementById(id);\nconst fmt = n => Math.max(0,Number(n)||0).toLocaleString('en-US');\nfunction toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}\nfunction showPage(name){syncTelegramViewport();window.scrollTo(0,0);document.scrollingElement?.scrollTo(0,0);state.activePage=name;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='leaderboard'){if(state.rankMode)renderRankPage();else loadLeaderboard();}if(name==='squad')renderReferrals();if(name==='daily')renderDailyPage();}\nasync function api(path,body){const res=await fetch(`${API_BASE}/api${path}`,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await res.json().catch(()=>({error:'Invalid server response'}));if(!res.ok)throw new Error(data.error||`Request failed (${res.status})`);return data}\nfunction hideLoader(){ $('loadingScreen').classList.add('hidden');setTimeout(()=>$('loadingScreen').remove(),300); }\nfunction updateRegenTimer(){clearInterval(regenTimer);const el=$('regenText');if(!el||!state.user)return;const at=Number(state.user.nextEnergyAt||0);const energy=Number(state.user.energy||0);const max=Number(state.user.maxEnergy||0);if(energy>0||!at){el.textContent=energy>=max?'FULL':'READY';return;}const tick=()=>{const sec=Math.max(0,Math.ceil((at-Date.now())/1000));if(sec<=0){el.textContent='READY';clearInterval(regenTimer);setTimeout(()=>boot(),500);return;}const hh=String(Math.floor(sec/3600)).padStart(2,'0');const mm=String(Math.floor((sec%3600)/60)).padStart(2,'0');const ss=String(sec%60).padStart(2,'0');el.textContent=hh+':'+mm+':'+ss};tick();regenTimer=setInterval(tick,1000)}\nfunction renderTaskState(){const s=state.user?.taskStatus||{};document.querySelectorAll('[data-claim-task]').forEach(b=>{const claimed=!!s[b.dataset.claimTask];b.disabled=claimed;b.textContent=claimed?'Claimed':'Claim';b.classList.toggle('claimed',claimed);});}\nfunction updateUI(){const u=state.user;if(!u)return;$('balance').textContent=fmt(u.points);$('boostBalance').textContent=fmt(u.points);$('taskBalance').textContent=fmt(u.points);$('energyText').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('profileEnergy').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('energyFill').style.width=`${Math.max(0,Math.min(100,u.energy/u.maxEnergy*100))}%`;$('tapPower').textContent=`+${u.tapPower}`;const rr=$('refRewardValue');if(rr)rr.textContent='+'+fmt(state.config?.referralBonus||250);$('streak').textContent=`${u.streak||0} days`;$('rank').textContent=u.rank||'Rookie';$('username').textContent=u.firstName||'Miner';$('avatar').textContent=(u.firstName||'N').slice(0,1).toUpperCase();$('profileAvatar').textContent=(u.firstName||'N').slice(0,1).toUpperCase();$('profileName').textContent=u.firstName||'Nexus Miner';$('telegramId').textContent=u.telegramId?`Telegram ID · ${u.telegramId}`:'Preview mode';$('profilePoints').textContent=fmt(u.points);$('profileReferrals').textContent=fmt(u.referralCount||0);$('profileRank').textContent=u.rank||'Rookie';$('profileStreak').textContent=fmt(u.streak||0);$('profileEnergy').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('profileUsername').textContent=u.username?`@${u.username}`:'No username';$('refCount').textContent=fmt(u.referralCount||0);$('refTotal').textContent=`${fmt(u.referralCount||0)} invited`;$('profileLevel').textContent=(u.upgrades?.multitap||0)+(u.upgrades?.energy||0)+(u.upgrades?.recharge||0);$('multiLevel').textContent=u.upgrades?.multitap||0;$('energyLevel').textContent=u.upgrades?.energy||0;$('rechargeLevel').textContent=u.upgrades?.recharge||0;$('multiCost').textContent=fmt(u.upgradeCosts?.multitap||100);$('energyCost').textContent=fmt(u.upgradeCosts?.energy||150);$('rechargeCost').textContent=fmt(u.upgradeCosts?.recharge||125);renderTaskState();updateRegenTimer();}\nfunction demoUser(){return {telegramId:null,firstName:'NexusMiner',username:'',energyCost:10,points:12450,energy:780,maxEnergy:1000,tapPower:1,streak:3,rank:rankFromPoints(12450),referralCount:2,upgrades:{multitap:0,energy:0,recharge:0},upgradeCosts:{multitap:100,energy:150,recharge:125},referrals:[],nextEnergyAt:Date.now()+3600000}}\nasync function boot(){const initData=tg?.initData||'';try{if(tg){tg.ready();syncTelegramViewport();tg.onEvent?.('viewportChanged',syncTelegramViewport);tg.onEvent?.('themeChanged',syncTelegramViewport);}window.addEventListener('resize',syncTelegramViewport,{passive:true});window.visualViewport?.addEventListener('resize',syncTelegramViewport,{passive:true});syncTelegramViewport();if(!initData){state.demo=true;state.user=demoUser();toast('Preview mode — open from your Telegram bot to mine for real.');hideLoader();updateUI();return;}const data=await api('/session',{initData,startParam:String(tg?.initDataUnsafe?.start_param||'')});state.user=data.user;state.user.energyCost=Number(state.user.energyCost||10);state.config=data.config||{};const adminNav=document.querySelector('.admin-nav');if(adminNav)adminNav.style.display=state.config.isAdmin?'flex':'none';const ownerAdminWrap=document.getElementById('ownerAdminWrap');if(ownerAdminWrap)ownerAdminWrap.style.display=state.config.isAdmin?'block':'none';hideLoader();updateUI();if(!state.demo){loadManagedLinks();loadAdHistory();}}catch(err){hideLoader();if(!initData){state.demo=true;state.user=demoUser();updateUI();toast(`Preview mode: ${err.message}`);}else{state.ready=false;toast(err.message||'Unable to load your NexusGram account. Reopen the Mini App.')}}}\nfunction floatPoint(event,amount){const el=document.createElement('span');el.className='float-point';el.textContent=`+${amount}`;const rect=$('balance').getBoundingClientRect();el.style.left=`${rect.left+rect.width*.5+Math.random()*46-23}px`;el.style.top=`${rect.top+rect.height*.5+Math.random()*18-9}px`;el.style.transform='translate(-50%,-50%)';$('floatLayer').appendChild(el);setTimeout(()=>el.remove(),750)}\nlet tapQueue=0,tapTimer=null,tapSending=false;\nfunction tapMine(event){\n if(!state.user)return;\n if(state.demo){const cost=Number(state.user.energyCost||10);if(Number(state.user.energy||0)<=0)return toast('Energy depleted — wait for the timer');const charge=Math.min(cost,Number(state.user.energy||0));state.user.energy=Math.max(0,state.user.energy-charge);if(state.user.energy<=0)state.user.nextEnergyAt=Date.now()+3600000;state.user.points+=state.user.tapPower;updateUI();floatPoint(event,state.user.tapPower);return;}\n const cost=Number(state.user.energyCost||10);if(Number(state.user.energy||0)<=0)return toast('Energy depleted — wait for the timer');\n const charge=Math.min(cost,Number(state.user.energy||0));\n state.user.energy=Math.max(0,state.user.energy-charge);state.user.points+=state.user.tapPower;updateUI();floatPoint(event,state.user.tapPower);\n tapQueue++;\n if(!tapTimer)tapTimer=setTimeout(flushTaps,20);\n}\nasync function flushTaps(){\n tapTimer=null;if(tapSending||tapQueue<=0)return;\n tapSending=true;const count=Math.min(tapQueue,20);tapQueue-=count;\n try{const result=await api('/tap-batch',{initData:tg.initData,count});if(tapQueue===0){state.user=result.user;updateUI();}}\n catch(e){if(tapQueue===0){try{const fresh=await api('/session',{initData:tg.initData,startParam:String(tg?.initDataUnsafe?.start_param||'')});state.user=fresh.user;state.config=fresh.config||state.config;updateUI();}catch{}}else{tapQueue=0;try{const fresh=await api('/session',{initData:tg.initData,startParam:String(tg?.initDataUnsafe?.start_param||'')});state.user=fresh.user;state.config=fresh.config||state.config;updateUI();}catch{}}toast(e.message);}\n finally{tapSending=false;if(tapQueue>0)tapTimer=setTimeout(flushTaps,20);}\n}\nasync function upgrade(kind){if(state.demo){const cost=state.user.upgradeCosts[kind];if(state.user.points<cost)return toast('Not enough points');state.user.points-=cost;state.user.upgrades[kind]++;state.user.upgradeCosts[kind]=Math.ceil(cost*1.65);if(kind==='multitap')state.user.tapPower++;if(kind==='energy'){state.user.maxEnergy+=250;state.user.energy=state.user.maxEnergy}updateUI();return toast('Upgrade applied in preview');}try{const r=await api('/upgrade',{initData:tg.initData,kind});state.user=r.user;updateUI();toast('Upgrade successful');}catch(e){toast(e.message)}}\nconst streakRewards=[50,75,100,150,200,300,500];\nlet dailyTimer=null;\nfunction formatCountdown(ms){const sec=Math.max(0,Math.ceil(ms/1000));const h=String(Math.floor(sec/3600)).padStart(2,'0');const m=String(Math.floor((sec%3600)/60)).padStart(2,'0');const s=String(sec%60).padStart(2,'0');return h+':'+m+':'+s}\nfunction updateDailyCountdown(){clearInterval(dailyTimer);const u=state.user;if(!u)return;const tick=()=>{const at=Number(u.nextDailyAt||0);const el=$('dailyNextText');const btn=$('dailyPageClaim');const stateEl=$('dailyState');const label=$('dailyClaimLabel');if(at&&Date.now()<at){const left=at-Date.now();if(el)el.textContent='Next check-in available in '+formatCountdown(left);if(stateEl)stateEl.textContent='LOCKED';if(label)label.textContent='WAIT '+formatCountdown(left);if(btn){btn.disabled=true;btn.style.opacity='.55';}}else{if(el)el.textContent='24-hour window complete. Check in now to claim your NXG reward.';if(stateEl)stateEl.textContent='READY';if(label)label.textContent='CHECK IN';if(btn){btn.disabled=false;btn.style.opacity='1';}clearInterval(dailyTimer)}};tick();dailyTimer=setInterval(tick,1000)}\nfunction renderDailyPage(){const u=state.user;if(!u)return;const streak=Math.max(0,Number(u.streak||0));const nextDay=Math.max(1,Math.min(7,streak+1));const base=Number(state.config?.dailyBase??50);const rewards=streakRewards.map(x=>Math.round(x*(base/50)));const reward=rewards[nextDay-1];$('dailyPageStreak').textContent=String(streak);$('dailyStreakValue').textContent=String(streak);$('dailyRewardValue').textContent=`+${reward} NXG`;$('dailyNextReward').textContent=`+${reward} NXG`;const box=$('dailyPageDays');if(box)box.innerHTML=rewards.map((r,i)=>`<div class=\"streak-day ${i+1===nextDay?'current':''} ${i+1<nextDay?'done':''}\"><span>DAY ${i+1}</span><b>+${r} NXG</b></div>`).join('');updateDailyCountdown()}\nasync function claimDailyFromPage(){await dailyClaim();renderDailyPage();}\nasync function dailyClaim(){if(state.demo){const now=Date.now();if(state.user.nextDailyAt&&now<state.user.nextDailyAt)return toast('Next daily check-in in '+formatCountdown(state.user.nextDailyAt-now));const day=Math.max(1,Math.min(7,((Number(state.user.streak||0)%7)+1)));const reward=streakRewards[day-1];state.user.points+=reward;state.user.streak++;state.user.nextDailyAt=now+86400000;updateUI();renderDailyPage();return toast('Daily reward claimed! +'+reward+' NXG Points');}try{const r=await api('/daily',{initData:tg.initData});state.user=r.user;updateUI();renderDailyPage();toast('Daily reward claimed! +'+(r.reward||50)+' NXG Points');}catch(e){toast(e.message)}}\nfunction inviteLink(){const id=state.user?.telegramId;if(!id)return '';const bot=(state.config?.botUsername||'Nexusgram_official_bot').replace(/^@/,'').trim()||'Nexusgram_official_bot';return `https://t.me/${bot}?startapp=${id}`}\nfunction shareInvite(){const link=inviteLink();if(!link)return toast('Referral link will be available after bot setup');const shareText='Launch NexusGram and mine NXG Points with me';if(tg?.openTelegramLink){tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(shareText)}`)}else if(navigator.share){navigator.share({title:'Launch NexusGram',text:shareText,url:link}).catch(()=>{})}else{navigator.clipboard?.writeText(link);toast('Launch link copied')}}\nasync function copyInvite(){const link=inviteLink();if(!link)return toast('Referral link will be available after bot setup');try{await navigator.clipboard.writeText(link);toast('Invite link copied')}catch{toast(link)}}\nasync function renderReferrals(){if(state.demo){$('refList').innerHTML='<div class=\"empty-state\">Preview: referral list will appear here after launch.</div>';return;}try{const r=await api('/referrals',{initData:tg.initData});$('refList').innerHTML=r.referrals.length?r.referrals.map(x=>`<div class=\"settings-row\"><span>${escapeHtml(x.firstName||'Nexus Miner')}</span><b>${x.active?'Active':'Joined'}</b></div>`).join(''):'<div class=\"empty-state\">Your squad is waiting. Invite your first friend!</div>';}catch(e){$('refList').innerHTML='<div class=\"empty-state\">Could not load squad.</div>'}}\nasync function loadLeaderboard(){if(state.demo){$('leaderList').innerHTML='<div class=\"empty-state\">Leaderboard is available after Telegram sign-in.</div>';return;}try{const r=await api('/leaderboard',{initData:tg.initData});$('leaderList').innerHTML=r.rows.map((x,i)=>{const medal='<span class=\"leader-number\">#'+(i+1)+'</span>';return '<div class=\"leader-row\"><div class=\"leader-rank\">'+medal+'</div><div class=\"leader-avatar\">'+escapeHtml((x.firstName||'N').slice(0,1).toUpperCase())+'</div><div class=\"leader-name\"><b>'+escapeHtml(x.firstName||'Nexus Miner')+'</b><small>Rank '+(i+1)+'</small></div><div class=\"leader-points\">'+fmt(x.points)+' pts</div></div>'}).join('')||'<div class=\"empty-state\">Be the first miner on the leaderboard.</div>'}catch(e){toast(e.message)}}\nconst rankTiers=[{name:'Rookie',min:0},{name:'Bronze',min:1000},{name:'Silver',min:5000},{name:'Gold',min:15000},{name:'Platinum',min:35000},{name:'Diamond',min:75000},{name:'Master',min:150000},{name:'Grandmaster',min:300000}];\nfunction renderRankPage(){const u=state.user||{points:0};let i=0;for(let n=0;n<rankTiers.length;n++){if(Number(u.points||0)>=rankTiers[n].min)i=n;else break;}const cur=rankTiers[i],next=rankTiers[i+1]||null,need=next?Math.max(0,next.min-Number(u.points||0)):0;const page=document.getElementById('page-leaderboard');if(!page)return;const h=page.querySelector('h1');if(h)h.textContent='Rank';const e=page.querySelector('.eyebrow');if(e)e.textContent='PROGRESSION';const box=document.getElementById('leaderList');if(!box)return;const icon='<span class=\"rank-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6l8-4z\"/></svg></span>';const summary='<div class=\"rank-summary\"><div class=\"rank-summary-top\"><div>'+icon+'<div><small>CURRENT RANK</small><h2>'+cur.name+'</h2></div></div><div class=\"rank-summary-status\">CURRENT</div></div><div class=\"rank-progress\"><div class=\"rank-progress-bar\"><span style=\"width:'+(next?Math.min(100,(Number(u.points||0)-cur.min)/Math.max(1,next.min-cur.min)*100):100)+'%\"></span></div><div class=\"rank-progress-meta\"><span>'+fmt(u.points)+' NXG</span><span>'+(next?fmt(next.min)+' NXG':'MAX RANK')+'</span></div></div><div class=\"rank-next\">'+(next?'<b>'+fmt(need)+' NXG</b><span>needed for '+next.name+'</span>':'<b>MAX RANK</b><span>You reached the highest tier</span>')+'</div></div>';const rows=rankTiers.map(t=>{const unlocked=t.min<=Number(u.points||0);const current=t.name===cur.name;const status=current?'CURRENT':unlocked?'UNLOCKED':'LOCKED';return '<div class=\"rank-tier '+(current?'is-current ':'')+(unlocked?'is-unlocked':'is-locked')+'\"><div class=\"rank-tier-icon\">'+icon+'</div><div class=\"rank-tier-main\"><b>'+t.name+'</b><small>Requirement · '+fmt(t.min)+' NXG</small></div><div class=\"rank-tier-status '+(current?'current':unlocked?'unlocked':'locked')+'\">'+status+'</div></div>'}).join('');box.innerHTML=summary+'<div class=\"rank-list-title\">RANK TIERS</div>'+rows;}\nconst taskStartedAt={};\nasync function openTask(which){\n const url=which==='news'?(state.config?.newsUrl||NEWS_URL||'https://t.me/nexusgram_official'):which==='youtube'?(state.config?.youtubeUrl||'https://youtube.com/@rajtilakeditz?si=OLEQqNUEq8H4240c'):(state.config?.chatUrl||CHAT_URL||'https://t.me/teslaspacex_roadster');\n if(!url)return toast('This official link is not configured yet');\n if(url.startsWith('https://t.me/')&&tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank','noopener');\n if(which==='news'){toast('Join the channel, then tap Claim reward.');return;}\n if(which==='youtube'){taskStartedAt.youtube=Date.now();toast('Watch for at least 5 seconds, then tap Claim reward.');}\n}\nfunction escapeHtml(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction setAdErrorState(show){\n const card=$('proAdCard'),err=$('adErrorBox'),btn=$('watchAdButton'),label=$('watchAdLabel'),icon=$('watchAdIcon'),badge=$('adStatusBadge'),note=$('adNote');\n if(card)card.classList.toggle('error-mode',!!show);\n if(err)err.style.display=show?'flex':'none';\n if(note)note.style.display=show?'none':'flex';\n if(btn){btn.classList.toggle('error-state',!!show);if(show)btn.disabled=false;}\n if(label)label.textContent=show?'TRY AGAIN':'WATCH AD';\n if(icon)icon.innerHTML=show?'<svg viewBox=\"0 0 24 24\"><path d=\"M12 9v4M12 17h.01\"/><path d=\"M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z\"/></svg>':'<svg viewBox=\"0 0 24 24\"><path d=\"M8 5v14l11-7L8 5z\"/></svg>';\n if(badge)badge.innerHTML=show?'<span class=\"pulse\"></span> NOT READY':'<span class=\"pulse\"></span> ACTIVE';\n}\nasync function loadAdHistory(){\n if(state.demo){const box=$('adHistoryList');if(box)box.innerHTML='<div class=\"ad-history-empty\"><div class=\"ad-history-empty-icon icon-svg\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2 4 6v6c0 5.4 3.5 9.2 8 10 4.5-.8 8-4.6 8-10V6l-8-4z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><b>Preview mode</b><span>Ad history available after Telegram sign-in</span></div>';return;}\n try{const r=await api('/ad-history',{initData:tg.initData});const used=Number(r.count||0);const left=Math.max(0,1000-used);const rem=$('adRemaining');if(rem)rem.textContent=fmt(left);const fill=$('adProgressFill');if(fill)fill.style.width=Math.min(100,(used/1000)*100)+'%';const box=$('adHistoryList');if(!box)return;if((r.rows||[]).length){box.innerHTML=r.rows.map(x=>{const t=new Date(Number(x.created_at||0));const timeStr=t.toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});return '<div class=\"vault-history-row\"><div class=\"history-icon icon-svg\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2 4 6v6c0 5 3.4 8.8 8 10 4.6-1.2 8-5 8-10V6l-8-4z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><div><b>Rewarded Ad</b><small>'+timeStr+'</small></div><strong>+100 NXG</strong></div>';}).join('');}else{box.innerHTML='<div class=\"ad-history-empty\"><div class=\"ad-history-empty-icon icon-svg\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2 4 6v6c0 5.4 3.5 9.2 8 10 4.5-.8 8-4.6 8-10V6l-8-4z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><b>No rewards yet</b><span>Watch your first ad to start earning history</span></div>';}}catch(e){const box=$('adHistoryList');if(box)box.innerHTML='<div class=\"ad-history-empty\"><div class=\"ad-history-empty-icon icon-svg\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 9v4M12 17h.01\"/><path d=\"M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z\"/></svg></div><b>Could not load</b><span>'+escapeHtml(e.message||'Try again')+'</span></div>';}}\nasync function watchRewardedAd(){\n if(state.demo)return toast('Open NexusGram from Telegram to watch rewarded ads');\n if(state.busy)return;\n const button=$('watchAdButton'),label=$('watchAdLabel');\n setAdErrorState(false);\n state.busy=true;if(button)button.disabled=true;if(label)label.textContent='LOADING AD...';\n try{\n  const sdkReady=await new Promise(resolve=>{\n   if(typeof window.show_12215196==='function')return resolve(true);\n   let waited=0;const timer=setInterval(()=>{\n    if(typeof window.show_12215196==='function'){clearInterval(timer);return resolve(true);}\n    waited+=250;if(waited>=10000){clearInterval(timer);resolve(false);}\n   },250);\n  });\n  if(!sdkReady){\n   setAdErrorState(true);\n   toast('Monetag SDK is not loaded. Please reopen the Mini App.');\n   return;\n  }\n  const ymid='nxg-'+String(state.user?.telegramId||'user')+'-'+crypto.randomUUID();\n  const result=await window.show_12215196({ymid,requestVar:'watch_ads'});\n  if(result?.reward_event_type!=='valued')throw new Error('This ad was not eligible for a reward.');\n  toast('Ad verified · +100 NXG is being credited');\n  setTimeout(async()=>{try{const fresh=await api('/session',{initData:tg.initData,startParam:String(tg?.initDataUnsafe?.start_param||'')});state.user=fresh.user;state.config=fresh.config||state.config;updateUI();await loadAdHistory();}catch{}},3500);\n }catch(e){\n  const msg=e.message||'Ad could not be completed';\n  if(msg.toLowerCase().includes('not loaded')||msg.toLowerCase().includes('not ready')){setAdErrorState(true);}\n  toast(msg);\n }finally{\n  state.busy=false;\n  if(button&&!button.classList.contains('error-state'))button.disabled=false;\n  if(label&&!button?.classList.contains('error-state'))label.textContent='WATCH AD';\n }\n}\ndocument.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{state.rankMode=false;showPage(b.dataset.page)}));\ndocument.querySelectorAll('[data-stat-go]').forEach(b=>{b.addEventListener('click',()=>{state.rankMode=true;showPage(b.dataset.statGo)});b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')state.rankMode=true,showPage(b.dataset.statGo)});});document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));$('tapButton').addEventListener('click',tapMine);document.querySelectorAll('[data-upgrade]').forEach(b=>b.addEventListener('click',()=>upgrade(b.dataset.upgrade)));$('dailyPageClaim')?.addEventListener('click',claimDailyFromPage);$('shareButton').addEventListener('click',shareInvite);$('copyButton').addEventListener('click',copyInvite);\ndocument.querySelectorAll('[data-task]').forEach(b=>b.addEventListener('click',()=>openTask(b.dataset.task)));\nasync function claimTask(which){\n if(state.demo)return toast('Open the app from Telegram to claim rewards');\n try{const r=await api('/task-reward',{initData:tg.initData,task:which,startedAt:taskStartedAt[which]||0});state.user=r.user;updateUI();toast('Task reward claimed! +'+r.reward+' NXG Points');const btn=document.querySelector('[data-claim-task=\"'+which+'\"]');if(btn){btn.disabled=true;btn.textContent='Claimed';}}catch(e){toast(e.message)}\n}\ndocument.querySelectorAll('[data-claim-task]').forEach(b=>b.addEventListener('click',()=>claimTask(b.dataset.claimTask)));\nasync function redeemCode(){if(state.demo)return toast('Open NexusGram from Telegram to redeem');const input=$('redeemCodeInput');const code=String(input?.value||'').trim();if(!code)return toast('Enter the redeem code');try{const r=await api('/redeem',{initData:tg.initData,code});state.user=r.user;updateUI();if(input)input.value='';toast('Redeemed successfully! +'+r.reward+' NXG Points');}catch(e){toast(e.message)}}\nlet managedLinks=[];\nfunction linkIcon(type){const p={telegram:'M12 2 3 6v5c0 5.2 3.7 9.5 9 11 5.3-1.5 9-5.8 9-11V6l-9-4Z',youtube:'M4 7.5A2.5 2.5 0 0 1 6.5 5h11A2.5 2.5 0 0 1 20 7.5v9a2.5 2.5 0 0 1-2.5 2.5h-11A2.5 2.5 0 0 1 4 16.5v-9ZM10 9l5 3-5 3V9Z',x:'M5 4h4l3 4 3.5-4H20l-5.5 7L20 20h-4l-3.5-4H4l5.5-7L5 4Z',other:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm1 5h-2v6h6v-2h-4V7Z'};return p[type]||p.other}\nfunction renderManagedLinks(){const box=$('managedLinksList');if(!box)return;if(!managedLinks.length){box.innerHTML='<div class=\"info-note\">No extra missions are active right now.</div>';return;}box.innerHTML=managedLinks.map(l=>{const claimed=!!state.user?.taskStatus?.['link:'+l.id];return '<div class=\"task-card managed-task\"><div class=\"task-icon icon-svg\"><svg viewBox=\"0 0 24 24\"><path d=\"'+linkIcon(l.type)+'\"/></svg></div><div class=\"task-copy\"><b>'+escapeHtml(l.title)+'</b><p>'+escapeHtml(l.description||'Complete this mission to earn NXG Points.')+'</p><small>'+escapeHtml(String(l.type).toUpperCase())+' · +'+fmt(l.reward)+' NXG</small></div><button class=\"task-action managed-open\" data-link-id=\"'+l.id+'\">Open ↗</button><button class=\"task-action managed-claim '+(claimed?'claimed':'')+'\" data-link-claim=\"'+l.id+'\" '+(claimed?'disabled':'')+'>'+(claimed?'Claimed':'Claim')+'</button></div>'}).join('');box.querySelectorAll('[data-link-id]').forEach(b=>b.addEventListener('click',()=>openManagedLink(Number(b.dataset.linkId))));box.querySelectorAll('[data-link-claim]').forEach(b=>b.addEventListener('click',()=>claimManagedLink(Number(b.dataset.linkClaim))))}\nasync function loadManagedLinks(){try{const r=await api('/links',{initData:tg.initData});managedLinks=r.links||[];renderManagedLinks()}catch(e){const box=$('managedLinksList');if(box)box.innerHTML='<div class=\"info-note\">'+escapeHtml(e.message)+'</div>'}}\nfunction openManagedLink(id){const l=managedLinks.find(x=>Number(x.id)===Number(id));if(!l)return;taskStartedAt['link:'+id]=Date.now();if(l.url.startsWith('https://t.me/')&&tg?.openTelegramLink)tg.openTelegramLink(l.url);else window.open(l.url,'_blank','noopener');toast(l.type==='telegram'?'Join the channel, then tap Claim reward.':'Keep this page open for 5 seconds, then tap Claim reward.')}\nasync function claimManagedLink(id){const key='link:'+id;try{const r=await api('/task-reward',{initData:tg.initData,task:key,startedAt:taskStartedAt[key]||0});state.user=r.user;updateUI();renderManagedLinks();toast('Mission reward claimed! +'+r.reward+' NXG Points')}catch(e){toast(e.message)}}\nasync function loadAdminLinks(){const r=await api('/admin/links',{initData:tg.initData,action:'list'});const box=$('adminLinksList');if(!box)return;const links=r.links||[];if(!links.length){box.innerHTML='<div class=\"info-note\">No mission links added.</div>';return;}box.innerHTML=links.map(l=>'<div class=\"admin-link-row\"><div><b>'+escapeHtml(l.title)+'</b><small>'+escapeHtml(l.type.toUpperCase())+' · '+escapeHtml(l.url)+' · +'+fmt(l.reward)+' NXG · '+(l.enabled?'ACTIVE':'OFF')+'</small></div><button class=\"task-action admin-delete-link\" data-id=\"'+l.id+'\">Delete</button></div>').join('');box.querySelectorAll('.admin-delete-link').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this mission link?'))return;try{await api('/admin/links',{initData:tg.initData,action:'delete',id:Number(b.dataset.id)});await loadAdminLinks();await loadManagedLinks();toast('Mission link deleted')}catch(e){toast(e.message)}}))}\nasync function openAdmin(){if(!state.config?.isAdmin)return;const r=await api('/admin/settings',{initData:tg.initData});for(const [k,v] of Object.entries(r.settings)){const el=document.getElementById('adm'+({tap_reward:'TapReward',energy_cost:'EnergyCost',daily_bonus:'DailyBonus',referral_bonus:'ReferralBonus',ad_reward:'AdReward',telegram_task_reward:'TelegramTaskReward',youtube_task_reward:'YoutubeTaskReward',redeem_code:'RedeemCode',redeem_reward:'RedeemReward',multitap_base_cost:'MultiCost',energy_base_cost:'EnergyCostBase',recharge_base_cost:'RechargeCost',news_url:'NewsUrl',chat_url:'ChatUrl',youtube_url:'YoutubeUrl'}[k]||''));if(el)el.value=v;}setAdminSwitch('mining_enabled',r.settings.mining_enabled);setAdminSwitch('ads_enabled',r.settings.ads_enabled);setAdminSwitch('maintenance_mode',r.settings.maintenance_mode);await loadAdminLinks();showPage('admin');}\nfunction setAdminSwitch(k,v){const b=document.querySelector('[data-admin-toggle=\"'+k+'\"]');if(b){b.dataset.value=String(v);const out=b.querySelector('b');if(out)out.textContent=String(v)==='1'?'ON':'OFF';}}\n$('watchAdButton')?.addEventListener('click',watchRewardedAd);$('openAdHistory')?.addEventListener('click',()=>{const m=$('adHistoryModal');if(m){m.classList.add('open');m.setAttribute('aria-hidden','false');loadAdHistory();}});document.querySelectorAll('[data-close-ad-history]').forEach(el=>el.addEventListener('click',()=>{const m=$('adHistoryModal');if(m){m.classList.remove('open');m.setAttribute('aria-hidden','true');}}));$('refreshAdHistory')?.addEventListener('click',loadAdHistory);$('profileButton')?.addEventListener('click',()=>showPage('profile'));$('ownerAdminButton')?.addEventListener('click',openAdmin);document.querySelector('.admin-nav')?.addEventListener('click',openAdmin);$('openRedeemButton')?.addEventListener('click',()=>{const box=$('redeemBox');if(box)box.classList.toggle('open');$('redeemCodeInput')?.focus();});$('redeemClaimButton')?.addEventListener('click',redeemCode);$('redeemCodeInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')redeemCode();});document.querySelectorAll('[data-admin-toggle]').forEach(b=>b.addEventListener('click',()=>setAdminSwitch(b.dataset.adminToggle,b.dataset.value==='1'?'0':'1')));\n$('adminAddLink')?.addEventListener('click',async()=>{try{const title=$('admLinkTitle')?.value.trim(),url=$('admLinkUrl')?.value.trim();if(!title||!url)return toast('Title and URL are required');await api('/admin/links',{initData:tg.initData,action:'add',type:$('admLinkType').value,title,url,reward:$('admLinkReward').value,description:$('admLinkDescription').value});$('admLinkTitle').value='';$('admLinkUrl').value='';$('admLinkDescription').value='';await loadAdminLinks();await loadManagedLinks();toast('Mission link added')}catch(e){toast(e.message)}});$('adminSave')?.addEventListener('click',async()=>{try{const map={tap_reward:'admTapReward',energy_cost:'admEnergyCost',daily_bonus:'admDailyBonus',referral_bonus:'admReferralBonus',ad_reward:'admAdReward',telegram_task_reward:'admTelegramTaskReward',youtube_task_reward:'admYoutubeTaskReward',redeem_code:'admRedeemCode',redeem_reward:'admRedeemReward',multitap_base_cost:'admMultiCost',energy_base_cost:'admEnergyCostBase',recharge_base_cost:'admRechargeCost',news_url:'admNewsUrl',chat_url:'admChatUrl',youtube_url:'admYoutubeUrl'};for(const [k,id] of Object.entries(map))await api('/admin/set',{initData:tg.initData,key:k,value:$(id).value});for(const k of ['mining_enabled','ads_enabled','maintenance_mode'])await api('/admin/set',{initData:tg.initData,key:k,value:document.querySelector('[data-admin-toggle=\"'+k+'\"]').dataset.value||'0'});toast('Admin settings saved');}catch(e){toast(e.message)}});$('profileButton').addEventListener('click',()=>showPage('profile'));\nboot();\n"
