function energyState(row,now,depletedAt){
  const max=Number(row.max_energy||START_ENERGY);
  const current=Math.max(0,Number(row.energy||0));
  const rechargeLevel=Math.max(0,Number(row.recharge_level||0));
  // Base 1 hour; each recharge level shortens wait ~12% (min 15 min)
  const interval=Math.max(15*60*1000, Math.floor(REGEN_INTERVAL_MS / (1 + 0.12 * rechargeLevel)));
  if(current<=0){
    const anchor=Number(depletedAt||now);
    const readyAt=anchor+interval;
    if(now>=readyAt)return {energy:max,max,regen:0,ticks:0,nextRegenAt:0,ready:true,interval};
    return {energy:0,max,regen:0,ticks:0,nextRegenAt:readyAt,ready:false,interval};
  }
  return {energy:Math.min(max,current),max,regen:0,ticks:0,nextRegenAt:0,ready:false,interval};
}
